input.command:
cd "$(pwd)"
cat > fixtures/primary.json <<'EOF'
{
  "axes": {
    "os": ["ubuntu-latest", "windows-latest"],
    "language": ["3.11", "3.12"]
  },
  "max_parallel": 2,
  "fail_fast": false,
  "max_size": 10
}
EOF
cat > fixtures/exclude.json <<'EOF'
{
  "axes": {
    "os": ["ubuntu-latest", "macos-latest"],
    "language": ["3.11", "3.12"]
  },
  "exclude": [{"os": "macos-latest", "language": "3.11"}],
  "fail_fast": true
}
EOF
cat > fixtures/include.json <<'EOF'
{
  "axes": {
    "fruit": ["apple", "pear"],
    "animal": ["cat", "dog"]
  },
  "include": [
    {"color": "green"},
    {"color": "pink", "animal": "cat"},
    {"fruit": "apple", "shape": "circle"},
    {"fruit": "banana"},
    {"fruit": "banana", "animal": "cat"}
  ]
}
EOF
cat > fixtures/features.json <<'EOF'
{
  "axes": {
    "os": ["ubuntu-latest"],
    "language": ["3.12"],
    "features": ["fast", "safe"]
  },
  "max_parallel": 4
}
EOF
cat > fixtures/error_maxsize.json <<'EOF'
{
  "axes": {
    "a": [1, 2, 3, 4, 5, 6],
    "b": [1, 2, 3, 4, 5, 6]
  },
  "max_size": 10
}
EOF
echo "fixtures created"; ls fixtures

